"""Build the small reusable M09 formal-evaluation control Dataset and Notebook."""
from __future__ import annotations
import argparse,ast,hashlib,json,shutil
from pathlib import Path
import sys
ROOT=Path(__file__).resolve().parents[1]

def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def canonical(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
def notebook():
 boot='''from pathlib import Path\nimport json, subprocess, sys, threading, time, os\nfrom IPython.display import FileLink, display\nINPUT=Path('/kaggle/input');WORKING=Path('/kaggle/working')\ncontrols=list(INPUT.rglob('m09_formal_eval_control.json'))\nif len(controls)!=1: raise RuntimeError(f'exactly one formal-eval control manifest required: {controls}')\ncontrol=controls[0]; data=json.loads(control.read_text(encoding='utf-8')); script=(control.parent/data['script']['path']).resolve()\nif not script.is_file(): raise RuntimeError('formal eval script missing')\nimport hashlib\ndef sha(p):\n h=hashlib.sha256(); f=open(p,'rb')\n for c in iter(lambda:f.read(1024*1024),b''):h.update(c)\n f.close(); return h.hexdigest()\nif sha(script)!=data['script']['sha256']: raise RuntimeError('formal eval script hash mismatch')\ncmd=[sys.executable,'-u',str(script),'--control-manifest',str(control),'--input-root',str(INPUT),'--working-root',str(WORKING)]\nprint('RUN:',cmd,flush=True); started=time.monotonic(); proc=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)\nfor line in proc.stdout: print(line.rstrip(),flush=True)\ncode=proc.wait(); print('exit=',code,'elapsed=',time.monotonic()-started,flush=True)\nif code!=0: raise RuntimeError(f'formal evaluation failed exit={code}')\nzip_path=WORKING/'guandan-marvel-formal-eval-iter0500.zip'\nif not zip_path.is_file(): raise RuntimeError('formal evaluation ZIP missing')\ndisplay(FileLink(str(zip_path)))\n'''
 nb={'cells':[{'cell_type':'markdown','metadata':{},'source':['# M09 iter500 Formal Evaluation / Champion\n','Inputs: control Dataset + segment0500 Notebook Output + r2 IPPO Pilot Notebook Output.\n']},{'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':[x+'\n' for x in boot.splitlines()]}],'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.13'}},'nbformat':4,'nbformat_minor':5};ast.parse(boot);return nb
def main(argv=None):
 ap=argparse.ArgumentParser();ap.add_argument('--output',type=Path,required=True);a=ap.parse_args(argv);out=a.output.resolve();
 if out.exists():shutil.rmtree(out)
 ds=out/'dataset';ds.mkdir(parents=True);script=ROOT/'scripts/m09_kaggle_formal_eval.py';legacy=ROOT/'runs/a07probe/local_fast/ippo/ippo_update_000001_90453d2696194fc2b755820939dcbed2_periodic.pt';shutil.copy2(script,ds/script.name);shutil.copy2(legacy,ds/'legacy_v1_anchor.pt')
 body={'schema':'guandan-marvel-m09-formal-eval-control-v1','created_at':'2026-10-14','script':{'path':script.name,'sha256':sha(ds/script.name)},'legacy_checkpoint':{'path':'legacy_v1_anchor.pt','sha256':sha(ds/'legacy_v1_anchor.pt')},'expected':{'source_commit':'e5c82e7c27fb366800e9722c9e8e4720df7db01f','source_manifest_hash':'fd8853e379b3bb2a6eefc00474bda9c200aa49139bcbea841a4ffa7c105e6fca','runtime_binary_sha256':'5b9a1fd71361c27cdecafe8d6612165e8cfbdddd948b47679cfb6956f6e17a83','candidate_iteration':500,'candidate_checkpoint_manifest_hash':'1cb0b58c9027d2bae096aa6f4d23d5c007812b444d1f3abe9f1f44df7b51219b','initial_champion_sha256':'b00a2c178e8b3e99d80418ae283a785285639b8172a0d96232beef7233b9d41c'},'claims':{'final_holdout':False,'strength_claim':False,'m09_accepted':False}};x={**body,'manifest_hash':canonical(body)};(ds/'m09_formal_eval_control.json').write_text(json.dumps(x,indent=2,sort_keys=True,ensure_ascii=False)+'\n',encoding='utf-8');(out/'guandan_marvel_m09_iter0500_formal_eval.ipynb').write_text(json.dumps(notebook(),indent=2,ensure_ascii=False)+'\n',encoding='utf-8');(out/'README.md').write_text('# M09 iter500 formal evaluation\n\nCreate one private Dataset from `dataset`. In the Notebook add: this control Dataset, the segment0500 Notebook Output, and the r2 IPPO Pilot Notebook Output. Use T4 x2 and Run All. No large checkpoint/recovery re-upload is needed.\n',encoding='utf-8');print(json.dumps({'output':str(out),'control_manifest_hash':x['manifest_hash'],'script_sha256':x['script']['sha256'],'legacy_sha256':x['legacy_checkpoint']['sha256']},indent=2));return 0
if __name__=='__main__':raise SystemExit(main())
